#!/usr/bin/env python3
import argparse
import datetime
import json
import logging
import sys
import time


class JsonFormatter(logging.Formatter):
    def format(self, record):
        ts = datetime.datetime.fromtimestamp(record.created, datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
        payload = {
            'timestamp': ts,
            'level': record.levelname,
            'message': record.getMessage(),
            'service': 'myapp',
        }
        return json.dumps(payload, separators=(',', ':'))


def parse_args():
    parser = argparse.ArgumentParser(description='myapp JSON event logger')
    parser.add_argument('--log-level', default='INFO', type=lambda s: s.upper(), choices=['INFO', 'WARN', 'ERROR'])
    return parser.parse_args()


def main():
    args = parse_args()
    level = {'INFO': logging.INFO, 'WARN': logging.WARNING, 'ERROR': logging.ERROR}[args.log_level]
    handler = logging.StreamHandler(sys.stdout)
    handler.setFormatter(JsonFormatter())
    logger = logging.getLogger('myapp')
    logger.setLevel(level)
    logger.addHandler(handler)
    logger.propagate = False

    logger.info('Service started')
    counter = 0
    while True:
        time.sleep(10)
        counter += 1
        logger.info('Heartbeat %d', counter)
        if counter % 6 == 0:
            logger.warning('Queue depth elevated')
        if counter % 12 == 0:
            logger.error('Simulated processing failure')


if __name__ == '__main__':
    try:
        main()
    except KeyboardInterrupt:
        sys.exit(0)
